var RAW = String(result || '');
var OUT = [];
var ANCHOR = RAW.indexOf('class="ucontent"');
if (ANCHOR === -1) {
  OUT.push('<div class="ucontent"><div class="ctitle"><p>🔍 点此输入关键词搜索</p></div><a href="' + String(baseUrl) + '"></a></div>');
} else {
  var SEG = RAW.substring(ANCHOR);
  var RE = /<li>[\s\S]*?<\/li>/g;
  var M;
  while ((M = RE.exec(SEG)) !== null) {
    OUT.push(M[0]);
    if (OUT.length >= 60) break;
  }
}
result = OUT;

